#include <bits/stdc++.h>
using namespace std;
#define int long long

void solve() {
    int n ;
    cin >> n ;
    vector <int> a(10 * n + 1) ;
    vector <int> p4(10 * n + 1) , p3(10 * n + 1) ;
    for(int i = 1 ; i <= 3 * n ; i ++) cin >> a[i] ;
    sort(a.begin() + 1 , a.end()) ;
    reverse(a.begin() + 1 , a.end()) ;
    
    for(int i = 1 ; i <= 3 * n ; i ++) {
        p4[i] = p4[i - 1] + 4 * a[i] ;
        p3[i] = p3[i - 1] + 3 * a[i] ;
    }
   // cout << p4[3] - p4[1] + p3[6] - p3[3] + 6 * a[1]<< endl ;
    int ans = p3[3 * n] ;
    int sum = 0 ;
    for(int i = 0 ; i <= n ; i ++) {
        sum += a[i] ;
        int cur = sum * 6 ;
        int end = i + (n - i) * 3 ;
    //    cout << cur << " " ;
        ans = max(ans , cur + p3[end] - p3[i]) ;
        if(i == n) break ;
        int l = 1 ;
        int r = (n - i) * 2 ;
        int c2 = 0 ;
        while(l <= r) {
            int mid = (l + r) / 2 ;
            int idx = i + mid * 2 ;
            if(a[idx] + a[idx - 1] > 3 * a[end - mid + 1]) {
                c2 = mid ;
                l = mid + 1 ;
            } else r = mid - 1 ;
        }
        
        ans = max(ans , cur + p4[i + c2 * 2] - p4[i] + p3[i + 2 * c2 + 3 * (n - (i + c2))] - p3[i + 2 * c2]) ;
    }
   // cout << endl ;
    cout << ans << endl ;
}
int32_t main() {
	// your code goes here
	int t ;
	cin >> t ;
	while(t --) solve() ;
}
